      "settings": {
        "title_override": "VIVIENNE",
        "description_override": "<p>For the woman who leaves room for the unexpected. The Vivienne pairs a softly slouching leather body with rolled handles, a braided upper edge and warm gold accents. Its relaxed folds bring an easy warmth to a tailored coat, a familiar pair of jeans, and whatever the afternoon becomes.</p><p>Vegetable-tanned leather gives the Vivienne its tactile character. Look closely at the grain, the smoother trim and the stitching that follows each curve: the interest lies in how the surfaces meet, with enough softness for the silhouette to settle naturally.</p>",
        "fact_material": "Vegetable-tanned leather",
        "fact_detail": "Made by artisans with 10 years of experience",
        "preorder_lead_time": "Stock expected October 2026",
        "show_facts": true,
        "show_policies": false,
        "show_shipping_summary": false,
        "fact_carry": "Stock expected October 2026",
        "lead_time": "Stock expected October 2026"
